-- policy_member_test_sql
BEGIN; DO $$ DECLARE actor uuid; member uuid:=gen_random_uuid(); payload jsonb; result jsonb; BEGIN SELECT user_id INTO actor FROM public.user_roles WHERE role='superadmin' LIMIT 1; INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(member,'integral-controlled-test-'||member||'@example.invalid','{}',now()); payload:=jsonb_build_object('full_name','Controlled test','email','controlled@example.invalid','roles',jsonb_build_array('vendedor'),'product_ids',coalesce((select jsonb_agg(id) from (select id from public.products where is_active and deleted_at is null limit 1) p),'[]'::jsonb),'warehouse_ids',coalesce((select jsonb_agg(id) from (select id from public.warehouses where is_active limit 1) w),'[]'::jsonb),'jobs','[]'::jsonb,'access','[]'::jsonb,'deals',jsonb_build_array(jsonb_build_object('label','Test','comp_type','percent','amount',5,'currency','BRL','period','per_sale'))); result:=public.integral_configure_new_member(actor,member,payload); IF NOT EXISTS(SELECT 1 FROM public.integral_member_rules WHERE user_id=member) THEN RAISE EXCEPTION 'Test failure'; END IF; RAISE NOTICE 'Atomic member configuration passed'; END $$; ROLLBACK;

-- policy_grants_test_sql
