-- policy_create_order_test_sql
BEGIN; DO $$ DECLARE actor uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); wh uuid:=gen_random_uuid(); request jsonb; quote jsonb; first_sale jsonb; second_sale jsonb; rid uuid:=gen_random_uuid(); BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(actor,'integral-create-test-'||actor||'@example.invalid','{}',now()); PERFORM set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.user_roles WHERE role='superadmin' LIMIT 1),true); INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Controlled sale category',true,true); INSERT INTO public.inventory_items(id,product_id,name,unit,currency,cost,price,quantity,reserved,is_active,is_demo) VALUES(item,prod,'Controlled sale item','UN','BRL',10,100,10,0,true,true); INSERT INTO public.warehouses(id,name,city,state,is_active) VALUES(wh,'Controlled sale warehouse','Test city','SP',true); INSERT INTO public.warehouse_inventory(warehouse_id,item_id,quantity,reserved) VALUES(wh,item,10,0); INSERT INTO public.product_users(user_id,product_id) VALUES(actor,prod); PERFORM set_config('request.jwt.claim.sub',actor::text,true); request:=jsonb_build_object('currency','BRL','exchange',jsonb_build_object('mode','automatic'),'warehouse_id',wh,'destination',jsonb_build_object('country','Brasil','state','SP','city','Test city','address','Test address','number','1','recipient_name','Controlled customer','phone','12345'),'customer',jsonb_build_object('name','Controlled customer','phone','12345'),'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2,'discount_percent',0)),'notes','Controlled create'); quote:=public.seller_portal_quote(request); first_sale:=public.integral_seller_create_order(request,rid,quote,NULL); second_sale:=public.integral_seller_create_order(request,rid,quote,NULL); IF first_sale->>'id' IS DISTINCT FROM second_sale->>'id' OR (SELECT count(*) FROM public.orders WHERE seller_id=actor)<>1 THEN RAISE EXCEPTION 'Sale idempotency failed'; END IF; IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=(first_sale->>'id')::uuid AND seller_id=actor AND customer_id IS NOT NULL AND warehouse_id=wh) THEN RAISE EXCEPTION 'Sale customer linkage failed'; END IF; END $$; ROLLBACK;

-- policy_crm_test_sql
BEGIN; DO $$ DECLARE actor uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); pipe uuid; stage uuid; opportunity uuid; BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(actor,'integral-crm-test-'||actor||'@example.invalid','{}',now()); PERFORM set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.user_roles WHERE role='superadmin' LIMIT 1),true); INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Controlled CRM category',true,true); INSERT INTO public.product_users(user_id,product_id) VALUES(actor,prod); SELECT id INTO pipe FROM public.pipelines WHERE product_id=prod AND is_default LIMIT 1; IF pipe IS NULL THEN INSERT INTO public.pipelines(product_id,name,is_default) VALUES(prod,'Controlled pipeline',true) RETURNING id INTO pipe; END IF; SELECT id INTO stage FROM public.pipeline_stages WHERE pipeline_id=pipe ORDER BY position LIMIT 1; IF stage IS NULL THEN INSERT INTO public.pipeline_stages(pipeline_id,name,position) VALUES(pipe,'Controlled stage',1) RETURNING id INTO stage; END IF; PERFORM set_config('request.jwt.claim.sub',actor::text,true); opportunity:=public.estadual_seller_crm_create(jsonb_build_object('product_id',prod,'name','Controlled CRM customer','phone','12345','currency','BRL','potential_value',100)); IF NOT EXISTS(SELECT 1 FROM public.customer_products WHERE id=opportunity AND owner_id=actor AND product_id=prod) THEN RAISE EXCEPTION 'CRM ownership failed'; END IF; PERFORM public.estadual_seller_crm_move(opportunity,stage); END $$; ROLLBACK;